(()=>{
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=null,model=null,reportText='',view='discover';
const steps=['discover','investigate','teach','scope','report'];
const format=n=>n===null?'Unavailable':Number(n).toFixed(1);
function scope(){return {objective:$('case-objective').value.trim(),target:$('case-target').value.trim(),owner:$('case-owner').value,review:$('case-review').value};}
function show(next,focus=false){if(!steps.includes(next))return;view=next;document.querySelectorAll('[data-caseview]').forEach(b=>{const selected=b.dataset.caseview===next;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});steps.forEach(id=>$('case-'+id+'-panel').hidden=id!==next);if(next==='report')renderReport();if(focus)$('case-tab-'+next).focus();}
document.querySelectorAll('[data-caseview]').forEach(b=>{b.onclick=()=>show(b.dataset.caseview);b.onkeydown=e=>{let i=steps.indexOf(view),n;if(e.key==='ArrowRight')n=steps[(i+1)%steps.length];else if(e.key==='ArrowLeft')n=steps[(i+steps.length-1)%steps.length];else if(e.key==='Home')n=steps[0];else if(e.key==='End')n=steps.at(-1);if(n){e.preventDefault();show(n,true);}};});
document.querySelectorAll('[data-casego]').forEach(b=>b.onclick=()=>show(b.dataset.casego,true));
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function roles(){if(!data)return;const team=$('case-team').value,existing=$('case-role').value;const options=[...new Map(data.events.filter(e=>!team||e.team===team).map(e=>[e.roleId,e.role])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));$('case-role').innerHTML='<option value="">All roles in team</option>'+options.map(([id,label])=>'<option value="'+esc(id)+'">'+esc(label)+'</option>').join('');$('case-role').value=options.some(([id])=>id===existing)?existing:'';}
function filters(){return {team:$('case-team').value,role:$('case-role').value,cohort:$('case-cohort').value,stage:$('case-stage').value,sla:$('case-sla').value};}
function renderReport(){
 if(!model){$('case-report-content').innerHTML='<p>No valid case analysis is available. Check the investigation settings.</p>';['case-print','case-report-download'].forEach(id=>$(id).disabled=true);return;}
 const settings=scope();if(CaseEngine.timestamp(settings.review)===null||settings.review<model.asOf){$('case-report-content').innerHTML='<p>Choose a valid proposed review date on or after '+esc(model.asOf)+' in Scope & handover.</p>';['case-print','case-report-download'].forEach(id=>$(id).disabled=true);return;}
 reportText=CaseEngine.report(model,settings);
 $('case-report-content').innerHTML=reportText.split('\n\n').map(part=>{const lines=part.split('\n'),first=lines.shift();if(first.startsWith('# ')||first.startsWith('## ')){const tag=first.startsWith('## ')?'h3':'h2';return '<'+tag+'>'+esc(first.replace(/^#+ /,''))+'</'+tag+'>'+(lines.length?'<p>'+esc(lines.join('\n')).replace(/\n/g,'<br>')+'</p>':'');}return '<p>'+esc(part).replace(/\n/g,'<br>')+'</p>';}).join('');
 ['case-print','case-report-download'].forEach(id=>$(id).disabled=false);
}
function render(){
 if(!data)return;
 try{model=CaseEngine.analyse(data,filters());$('case-status').textContent='Fictional history · '+data.asOf+' · '+(model.filters.team||'all teams')+' · '+(model.filters.cohort||'both entry cohorts');$('case-metrics').disabled=false;
 const bottleneck=model.bottleneck;
 $('case-analysis').innerHTML='<div class="case-stats"><article class="case-stat"><span>Applications in selected cohort</span><strong>'+model.applications+'</strong><small>'+model.eventCount+' events in selected stages</small></article><article class="case-stat"><span>Valid duration coverage</span><strong>'+format(model.coverage)+'%</strong><small>'+model.validDurations+' valid / '+model.eventCount+' selected events · '+model.excluded+' excluded</small></article><article class="case-stat"><span>Longest completed-stage median</span><strong>'+(bottleneck?format(bottleneck.median)+' days':'Unavailable')+'</strong><small>'+(bottleneck?esc(bottleneck.stage)+' · n='+bottleneck.completed:'Requires at least five valid completed durations')+'</small></article></div>'+
 '<div class="case-table-wrap"><table class="case-table"><caption style="text-align:left;padding:18px;font-weight:600">Stage movement · fictional evidence</caption><thead><tr><th>Stage / entered</th><th>Progression among resolved</th><th>Completed-stage median</th><th>Active waiting time</th><th>Data coverage</th></tr></thead><tbody>'+model.rows.map(r=>'<tr><td><b>'+esc(r.stage)+'</b><small>'+r.entered+' applications entered</small></td><td>'+format(r.progression)+'%<small>'+r.progressed+' progressed or hired / '+r.resolved+' resolved exits</small><div class="case-bar" aria-hidden="true"><i style="width:'+Math.max(0,Math.min(100,r.progression??0))+'%"></i></div></td><td>'+format(r.median)+' days<small>n='+r.completed+' valid completed stages'+(r.completed<5?' · small sample':'')+'</small></td><td>'+r.active+' active<small>'+format(r.waitingMedian)+' days median · '+r.overdue+' valid waits above '+model.filters.sla+' days</small></td><td>'+r.excluded+' excluded<small>from duration calculations'+(r.validActive<r.active?' · some active ages unavailable':'')+'</small></td></tr>').join('')+'</tbody></table></div>'+
 '<div class="case-grid"><article class="case-card case-tint"><span class="case-label">OBSERVATION → HYPOTHESIS</span><h3>'+(bottleneck?'Investigate '+esc(bottleneck.stage.toLowerCase())+'.':'Collect more evidence before choosing a bottleneck.')+'</h3><p>'+(bottleneck?'Its completed-stage median is '+format(bottleneck.median)+' days in this selection. Scheduling capacity, feedback delay and role mix are possible explanations. None is established by the median alone.':'No selected stage has five valid completed durations. A descriptive table is available, but a confident stage comparison is unsupported.')+'</p><p><b>What would change the recommendation?</b> Source reconciliation showing incorrect transitions; a different role mix; or scheduling evidence locating the delay elsewhere.</p></article><article class="case-card"><span class="case-label">TEST THE ALTERNATIVE</span><h3>Does the conclusion hold across teams and cohorts?</h3><div class="case-compare"><button data-case-team="Engineering" aria-pressed="'+(model.filters.team==='Engineering')+'">Engineering</button><button data-case-team="Commercial" aria-pressed="'+(model.filters.team==='Commercial')+'">Commercial</button><button data-case-cohort="October" aria-pressed="'+(model.filters.cohort==='October')+'">October cohort</button><button data-case-reset="true">Reset comparison</button></div><p>Changing a filter updates the evidence and report. Newer cohorts have less time to resolve. Avoid comparing progression percentages as if exposure time and role mix were identical.</p></article></div>'+
 '<div class="case-missing"><b>Method and limits.</b> One stage event per application/stage. Completed duration = exit − entry in calendar days. Active age = reference date − entry. Missing, invalid or future timestamps are excluded from durations; their observed outcomes still contribute to progression counts. Progression = progressed or hired / resolved exits; active applications are excluded. This is not cohort-adjusted conversion, time-to-fill or Quality of Hire. Threshold and sample-size rules are illustrative.</div>';
 $('case-analysis').querySelectorAll('[data-case-team]').forEach(b=>b.onclick=()=>{$('case-team').value=b.dataset.caseTeam;$('case-role').value='';roles();render();});
 $('case-analysis').querySelectorAll('[data-case-cohort]').forEach(b=>b.onclick=()=>{$('case-cohort').value=b.dataset.caseCohort;render();});
 $('case-analysis').querySelectorAll('[data-case-reset]').forEach(b=>b.onclick=()=>{$('case-team').value='Engineering';$('case-role').value='';$('case-cohort').value='';$('case-stage').value='';$('case-sla').value='7';roles();render();});
 renderReport();
 }catch(e){model=null;reportText='';$('case-status').textContent=e.message;$('case-analysis').innerHTML='';$('case-metrics').disabled=true;renderReport();}
}
$('case-team').onchange=()=>{roles();render();};['case-role','case-cohort','case-stage','case-sla'].forEach(id=>$(id).onchange=render);['case-objective','case-target','case-owner','case-review'].forEach(id=>$(id).oninput=renderReport);
$('case-metrics').onclick=()=>{if(model)download('fictional-case-filtered-metrics.csv',CaseEngine.metricsCSV(model),'text/csv;charset=utf-8');};
$('case-report-download').onclick=()=>{renderReport();if(!$('case-report-download').disabled)download('fictional-customer-engagement-report.md',reportText,'text/markdown;charset=utf-8');};
$('case-print').onclick=()=>{renderReport();if($('case-print').disabled)return;document.body.classList.add('case-print');try{window.print();}finally{document.body.classList.remove('case-print');}};
$('case-check-answer').onclick=()=>{const answer=document.querySelector('input[name="case-answer"]:checked'),output=$('case-quiz-feedback');output.hidden=false;output.textContent=!answer?'Choose a response first.':answer.value==='validate'?'That response tests the evidence before attributing a cause. Check completeness and role mix, inspect scheduling and feedback timestamps, then agree an action with the people who can change the process.':'This jumps from a descriptive metric to a cause or solution. Ask what is missing, compare like-for-like groups and inspect the underlying workflow before judging people or prescribing reminders.';};
$('case-guide').onclick=()=>download('customer-guide-interpreting-stage-delays.md',guide(),'text/markdown;charset=utf-8');
function guide(){return '# A customer guide to interpreting stage delays\n\nFictional educational example by John Hazelton.\n\n1. Define stage entry, exit and calendar-day conventions with the customer.\n2. Separate completed-stage duration from active waiting time.\n3. Report valid timestamps and excluded records; never turn missing dates into zero.\n4. Compare role mix, observation windows and sample sizes before assigning a cause.\n5. Inspect scheduling and feedback evidence; agree one owner and an escalation rule.\n6. Pilot a change, preserve definitions and review a comparable cohort. A change in a median does not prove causation.\n\nCSM: reinforce routine definitions and agreed actions. Escalate complex methodology or recurring data conflicts to RecOps. Document reproducible product gaps after excluding export/configuration causes.\n\nNo candidate scoring, individual performance judgement, time-to-fill or Quality of Hire claim is supported by stage history alone. No native Ashby configuration is claimed.\n';}
async function loadCase(){try{const response=await fetch('case-history.json');if(!response.ok)throw Error('History unavailable');data=await response.json();roles();$('case-stage').innerHTML='<option value="">All stages</option>'+data.stages.map(s=>'<option>'+esc(s)+'</option>').join('');render();}catch{$('case-status').textContent='The fictional history could not load. Reload to retry; the existing record health check is available below.';}}
loadCase();
})();
